// Carry the PR URL forward so downstream nodes can link to it.
const draft = $('Carry Base SHA').first().json;
const pr = $input.first().json;
const prUrl = pr.html_url;
const prNumber = pr.number;
if (!prUrl) {
  throw new Error('PR creation response missing html_url. Response: ' + JSON.stringify(pr).substring(0, 300));
}
return [{ json: { ...draft, prUrl, prNumber } }];

